/**
 * Validates input against inputSchema. See specs/hal-engine-tool-input-validation/spec.md
 */
async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
    throw new Error(`Unknown tool: ${name}`);
  }

  const resolvedDef = this.resolveDefinition(tool.definitionSource);
  let validate = this.compiledSchemas.get(resolvedDef.inputSchema);
  if (!validate) {
    validate = this.ajv.compile(resolvedDef.inputSchema);
    this.compiledSchemas.set(resolvedDef.inputSchema, validate);
  }

  if (!validate(input)) {
    const error = validate.errors?.[0];
    const message = error ? `${error.instancePath} ${error.message}`.trim() : 'Invalid input';
    return {result: message};
  }

  log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
  const rawResult = await tool.execute(input, context);

